use vstd::prelude::*;
use vstd::string::*;
use vstd::char::*;

verus! {

spec fn is_ascii_letter(c: char) -> bool {
    (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z')
}

spec fn check_condition_spec(txt: &str) -> bool {
    let chars = txt@.chars();
    chars.len() > 0 &&
    is_ascii_letter(chars[chars.len() - 1]) &&
    (chars.len() == 1 || chars[chars.len() - 2] == ' ')
}

fn check_if_last_char_is_a_letter(txt: &str) -> (result: bool)
    ensures
        result == check_condition_spec(txt),
{
    // First, check if the string is empty
    if txt.len() == 0 {
        return false;
    }
    
    // Convert to chars to work with Unicode scalar values
    let chars: Vec<char> = txt.chars().collect();
    
    // Check if we have at least one character (should be true since txt.len() > 0)
    if chars.len() == 0 {
        return false;
    }
    
    let last_char = chars[chars.len() - 1];
    
    // Check if last character is ASCII letter
    if !last_char.is_ascii_alphabetic() {
        return false;
    }
    
    // Check the conditions for being standalone
    if chars.len() == 1 {
        return true;
    }
    
    // Check if second-to-last character is space
    let second_last_char = chars[chars.len() - 2];
    second_last_char == ' '
}

} // verus!

